function validate([nums, operations]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 100000) return 'nums needs 1 to 10^5 values.';
  if (!Array.isArray(operations) || operations.length < 1 || operations.length > 100000) return 'operations needs 1 to 10^5 pairs.';
  const inRange = v => Number.isInteger(v) && v >= 1 && v <= 1000000;
  if (!nums.every(inRange)) return 'Each value of nums is a whole number from 1 to 10^6.';
  const present = new Set(nums);
  if (present.size !== nums.length) return 'The values of nums must be distinct.';
  for (const op of operations) {
    if (!Array.isArray(op) || op.length !== 2 || !inRange(op[0]) || !inRange(op[1])) return 'Each operation is a pair of whole numbers from 1 to 10^6.';
    if (!present.has(op[0])) return 'Each operation must replace a value currently in nums.';
    if (present.has(op[1])) return 'Each new value must not already be in nums.';
    present.delete(op[0]);
    present.add(op[1]);
  }
  return null;
}

