function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const large = size === 'large';
  const n = large ? int(1000, 2000) : int(1, 6);
  const m = large ? int(1000, 2000) : int(1, 7);
  const tight = rand() < 0.5;
  const top = tight ? n + (large ? int(1, 50) : int(1, 4)) : 1000000;
  const present = new Set();
  const nums = [];
  while (nums.length < n) {
    const value = int(1, top);
    if (present.has(value)) continue;
    present.add(value);
    nums.push(value);
  }
  const current = nums.slice();
  const operations = [];
  for (let k = 0; k < m; k++) {
    const at = int(0, n - 1);
    const from = current[at];
    let to = int(1, top);
    while (present.has(to)) to = int(1, top);
    present.delete(from);
    present.add(to);
    current[at] = to;
    operations.push([from, to]);
  }
  return [nums, operations];
}
